import fastify from "fastify";
import cors from "@fastify/cors";
import helmet from "@fastify/helmet";
import jwt from "@fastify/jwt";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import type { AppDependencies } from "./types.js";

export function createFastify(appDeps: AppDependencies) {
  const app = fastify({
    logger: true,
  });

  // 보안 및 CORS 설정
  app.register(cors);
  app.register(helmet);

  // JWT 설정
  app.register(jwt, {
    secret: appDeps.jwtSecret,
  });

  // Swagger 설정
  app.register(swagger, {
    openapi: {
      info: {
        title: "RealWorld API",
        description: "Fastify + Prisma + SQLite 기반 RealWorld 백엔드",
        version: "1.0.0",
      },
      servers: [
        { url: "http://localhost:3000", description: "Local development" },
      ],
    },
  });
  app.register(swaggerUi, {
    routePrefix: "/docs",
  });

  // JSON 본문 파서
  app.setJsonParser((body, opts) => {
    try {
      return JSON.parse(body);
    } catch (e) {
      opts.statusCode = 400;
      opts.error = new Error("Invalid JSON body");
      return null;
    }
  });

  // 모든 요청에 user 부착
  app.addHook("onRequest", async (req, reply) => {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith("Bearer ")) {
      try {
        const decoded = await app.jwt.verify(authHeader.slice(7));
        req.user = decoded;
      } catch {
        // 유효하지 않은 JWT는 무시됨
      }
    }
  });

  // 에러 핸들러
  app.setErrorHandler((error, request, reply) => {
    console.error("Error:", error);
    reply.status(error.statusCode || 500).send({
      error: error.message || "Internal Server Error",
    });
  });

  return app;
}

export type FastifyInstance = ReturnType<typeof createFastify>;

