import { compare, hash } from "bcryptjs";
import { randomUUID } from "crypto";
import type { RouteHandler } from "../types.js";
import type { FastifyInstance } from "../fastify.js";

export function registerAuthRoutes(app: FastifyInstance, deps: {
  prisma: import("@prisma/client").PrismaClient;
  jwtSecret: string;
}) {
  const { prisma } = deps;

  // 회원가입
  const register: RouteHandler = async (req, reply) => {
    const { email, username, password } = req.body;

    if (!email || !username || !password) {
      reply.code(422).send({ error: "email, username, password required" });
      return;
    }

    const existing = await prisma.user.findFirst({
      where: {
        OR: [{ email }, { username }],
      },
    });

    if (existing) {
      reply.code(422).send({ error: "User already exists" });
      return;
    }

    const hashedPassword = await hash(password, 10);
    const user = await prisma.user.create({
      data: {
        email,
        username,
        password: hashedPassword,
      },
      include: {
        profile: true,
      },
    });

    const token = app.jwt.sign({ id: user.id, email: user.email, username: user.username }, deps.jwtSecret);

    // password 제거
    const { password: _, ...userWithoutPassword } = user;

    reply.code(201).send({
      user: { ...userWithoutPassword, password: undefined },
      token,
    });
  };

  // 로그인
  const login: RouteHandler = async (req, reply) => {
    const { email, password } = req.body;

    if (!email || !password) {
      reply.code(422).send({ error: "email and password required" });
      return;
    }

    const user = await prisma.user.findUnique({
      where: { email },
      include: { profile: true },
    });

    if (!user) {
      reply.code(401).send({ error: "Invalid credentials" });
      return;
    }

    const isValid = await compare(password, user.password);
    if (!isValid) {
      reply.code(401).send({ error: "Invalid credentials" });
      return;
    }

    const token = app.jwt.sign({ id: user.id, email: user.email, username: user.username }, deps.jwtSecret);

    const { password: _, ...userWithoutPassword } = user;

    reply.send({
      user: { ...userWithoutPassword, password: undefined },
      token,
    });
  };

  app.post("/api/users", register);
  app.post("/api/users/login", login);
}

