import type { RouteHandler } from "../types.js";
import type { FastifyInstance } from "../fastify.js";

/**
 * RealWorld User/Profile API 엔드포인트
 *
 * GET    /api/users/:username       - 유저 프로필 조회
 * PUT    /api/users                 - 현재 유저 프로필 업데이트 (인증 필요)
 * GET    /api/user                  - 현재 로그인 유저의 프로필 (인증 필요)
 */
export function registerUserRoutes(app: FastifyInstance, deps: {
  prisma: import("@prisma/client").PrismaClient;
}) {
  const { prisma } = deps;

  // GET /api/users/:username - 유저 프로필 조회
  const getUserProfile: RouteHandler = async (req, reply) => {
    const { username } = req.params;

    const user = await prisma.user.findUnique({
      where: { username },
      include: { profile: true },
    });

    if (!user) {
      reply.code(404).send({ error: "User not found" });
      return;
    }

    const { password: _, ...userWithoutPassword } = user;
    reply.send({ user: { ...userWithoutPassword, password: undefined } });
  };

  // PUT /api/users - 현재 유저 프로필 업데이트 (JWT 인증 필요)
  const updateUser: RouteHandler = async (req, reply) => {
    if (!req.user) {
      reply.code(401).send({ error: "Authentication required" });
      return;
    }

    const { bio, image } = req.body;

    const user = await prisma.user.update({
      where: { id: req.user.id },
      data: {
        bio: bio ?? undefined,
        image: image ?? undefined,
      },
      include: { profile: true },
    });

    const { password: _, ...userWithoutPassword } = user;
    reply.send({ user: { ...userWithoutPassword, password: undefined } });
  };

  // GET /api/user - 현재 로그인 유저의 프로필 (JWT 인증 필요)
  const getCurrentUser: RouteHandler = async (req, reply) => {
    if (!req.user) {
      reply.code(401).send({ error: "Authentication required" });
      return;
    }

    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      include: { profile: true },
    });

    if (!user) {
      reply.code(404).send({ error: "User not found" });
      return;
    }

    const { password: _, ...userWithoutPassword } = user;
    reply.send({ user: { ...userWithoutPassword, password: undefined } });
  };

  app.get("/api/users/:username", getUserProfile);
  app.put("/api/users", updateUser);
  app.get("/api/user", getCurrentUser);
}

