import { compare, hash } from "bcryptjs";
import type { RouteHandler } from "../types.js";
import type { FastifyInstance } from "../fastify.js";

export function registerUsersRoutes(app: FastifyInstance, deps: {
  prisma: import("@prisma/client").PrismaClient;
}) {
  const { prisma } = deps;

  // GET /api/users/:username
  app.get("/api/users/:username", async (req, reply) => {
    const user = await prisma.user.findUnique({
      where: { username: req.params.username },
      include: { profile: true },
    });
    if (!user) {
      reply.code(404).send({ error: "User not found" });
      return;
    }
    const { password: _, ...safeUser } = user;
    reply.send({ user: safeUser });
  });

  // PUT /api/users - 현재 로그인 유저의 프로필 업데이트
  app.put("/api/users", async (req, reply) => {
    if (!req.user) {
      reply.code(401).send({ error: "Authentication required" });
      return;
    }

    const { username, email, password, bio, image } = req.body || {};
    const updateData: Record<string, any> = {};

    if (username) updateData.username = username;
    if (email) updateData.email = email;
    if (password) updateData.password = await hash(password, 10);
    if (bio !== undefined) updateData.bio = bio;
    if (image !== undefined) updateData.image = image;

    const user = await prisma.user.update({
      where: { id: req.user.id },
      data: updateData,
      include: { profile: true },
    });

    // 프로필도 동기화
    if (bio !== undefined || image !== undefined) {
      await prisma.profile.upsert({
        where: { userId: user.id },
        update: {
          bio: bio ?? undefined,
          image: image ?? undefined,
        },
        create: {
          userId: user.id,
          bio: bio ?? "",
          image: image ?? "",
        },
      });
    }

    const { password: _, ...safeUser } = user;
    reply.send({ user: safeUser });
  });

  // GET /api/user - 현재 로그인 유저 정보
  app.get("/api/user", async (req, reply) => {
    if (!req.user) {
      reply.code(401).send({ error: "Authentication required" });
      return;
    }

    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      include: { profile: true },
